    s+=f'''<body class="editorial stay-page" id="top">{navigation(lang,'stay')}<main id="main"><section class="section stay-layout"><div class="stay-welcome"><h1>{T('Your place<br>by the Pacific.','Tu lugar<br>junto al Pacífico.')}</h1><p>{T('The whole villa. Your favourite people. Find a few days to call your own.','Toda la villa. Tus personas favoritas. Encuentra unos días solo para ustedes.')}</p></div><div class="stay-photo">{photo(29,lang,True,sizes="(max-width: 700px) 100vw, 45vw")}<span>{T('Four bedrooms · Private infinity pool · Pacific views','Cuatro habitaciones · Piscina infinita privada · Vista al Pacífico')}</span><div class="stay-reassurance"><h2>{T('A personal welcome.','Una bienvenida personal.')}</h2><p>{T('Ask about the villa, a private chef or a special occasion. Your host is a conversation away.','Pregunta por la villa, un chef privado o una ocasión especial. Estamos a un mensaje de distancia.')}</p><a class="text-link" href="https://wa.me/50370528003" target="_blank" rel="noopener">{T('Talk to White Swan','Habla con White Swan')} ↗</a></div></div><div class="booking-card" id="booking"><ol class="booking-progress" aria-label="{T('Your stay request','Tu solicitud de estadía')}"><li aria-current="step">{T('Dates','Fechas')}</li><li>{T('Your details','Tus datos')}</li><li>{T('Request sent','Solicitud enviada')}</li></ol><h2>{T('Find your dates.','Elige tus fechas.')}</h2><p class="booking-mode-note">{T('Choose your dates to see nightly rates and property fees, then send your plans to White Swan. We’ll confirm the final total and terms before you pay.','Elige tus fechas para ver las tarifas por noche y los cargos de la propiedad. Luego envíanos tus planes. Confirmaremos el total final y las condiciones antes de que pagues.')}</p><form id="stay-request" hidden><div class="stay-date-selection"><button type="button" class="date-choice" data-pick="arrival" aria-controls="availability-days"><span>{T('Arrival','Llegada')}</span><strong>{T('Choose date','Elige fecha')}</strong></button><span class="date-journey" aria-hidden="true">→</span><button type="button" class="date-choice" data-pick="departure" aria-controls="availability-days"><span>{T('Departure','Salida')}</span><strong>{T('Choose date','Elige fecha')}</strong></button></div><details class="manual-dates"><summary>{T('Enter dates manually','Escribir fechas manualmente')}</summary><div class="booking-fields"><label>{T('Arrival','Llegada')}<input type="date" name="arrival" required></label><label>{T('Departure','Salida')}<input type="date" name="departure" required></label></div></details><label class="stay-guests">{T('Guests','Huéspedes')}<select name="guests">{''.join(f'<option value="{i}">{i} '+T('guest' if i==1 else 'guests','huésped' if i==1 else 'huéspedes')+'</option>' for i in range(1,11))}</select></label><section class="availability-browser" aria-label="{T('Villa availability','Disponibilidad de la villa')}" hidden><div class="calendar-heading"><button type="button" id="previous-month" aria-label="{T('Previous month','Mes anterior')}">←</button><h3 id="calendar-month" aria-live="polite"></h3><button type="button" id="next-month" aria-label="{T('Next month','Mes siguiente')}">→</button></div><div class="calendar-toolbar"><p class="calendar-instruction" role="status">{T('Choose your arrival date.','Elige tu fecha de llegada.')}</p><button type="button" id="clear-dates" hidden>{T('Clear dates','Borrar fechas')}</button></div><div id="availability-days" class="availability-days"></div><div class="calendar-legend"><span>{T('Available','Disponible')}</span><span class="legend-checkout" hidden>{T('Checkout only','Solo salida')}</span><span class="legend-unavailable">{T('Unavailable','No disponible')}</span><span class="legend-unknown">{T('Unverified','Sin verificar')}</span></div><p id="availability-status" class="fine" role="status"></p><button type="button" class="text-link" id="retry-calendar" hidden>{T('Try again','Intentar de nuevo')}</button></section><p class="stay-duration" role="status" aria-live="polite" hidden></p><p id="stay-error" class="form-status" role="alert"></p><button type="submit" class="button">{T('Check these dates','Consultar estas fechas')} →</button><p class="fine">{T('Calendar availability is checked through Hospitable, including connected Airbnb bookings. Dates are not held until your booking is confirmed.','Consultamos el calendario de Hospitable, incluidas las reservas conectadas de Airbnb. Las fechas no se apartan hasta confirmar la reserva.')}</p></form><noscript><p>{T('Contact your host with your dates and group size.','Contacta al anfitrión con tus fechas y el tamaño del grupo.')}</p><a class="button" href="https://wa.me/50370528003" target="_blank" rel="noopener">WhatsApp ↗</a></noscript><div id="stay-summary" hidden tabindex="-1"><h3>{T('Make it your stay.','Planea tu estadía.')}</h3><p class="stay-selection"></p><dl class="stay-summary-details"></dl><p id="stay-check-status" role="status"></p><form id="stay-contact" hidden><label>{T('Your name','Tu nombre')}<input name="name" autocomplete="name" minlength="2" maxlength="100" required></label><label>{T('Email','Correo electrónico')}<input name="email" type="email" autocomplete="email" maxlength="160" required></label><label>{T('WhatsApp number (optional)','Número de WhatsApp (opcional)')}<input name="phone" type="tel" autocomplete="tel" placeholder="+503" maxlength="30"></label><label>{T('Anything you’d like us to know? (optional)','¿Algo que debamos saber? (opcional)')}<textarea name="message" maxlength="1200" rows="2"></textarea></label><label class="honeypot" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><label class="consent"><input name="contactConsent" type="checkbox" required><span>{T('White Swan may use my details to respond to this stay request.','White Swan puede usar mis datos para responder a esta solicitud.')} <a href="{('/es/privacidad/' if lang=='es' else '/privacy/')}" target="_blank" rel="noopener">{T('Privacy','Privacidad')}</a></span></label><p class="form-status" role="alert"></p><button type="submit" class="button">{T('Send stay request','Enviar solicitud')} →</button><p class="fine">{T('No charge now. This is a request, not a confirmed reservation. Your host confirms capacity, price, cancellation and payment terms.','Sin cobro ahora. Es una solicitud, no una reserva confirmada. Tu anfitrión confirma capacidad, precio, cancelación y condiciones de pago.')}</p></form><div id="stay-received" hidden tabindex="-1"><h3>{T('Your plans are with us.','Ya recibimos tus planes.')}</h3><p class="receipt"></p><p>{T('White Swan will review your dates and get back to you. Your reservation is not confirmed yet.','Revisaremos tus fechas y te responderemos. Tu reserva todavía no está confirmada.')}</p></div><a class="text-link stay-whatsapp" href="https://wa.me/50370528003" target="_blank" rel="noopener">{T('Prefer to talk on WhatsApp?','¿Prefieres hablar por WhatsApp?')} ↗</a><button class="text-link" type="button" id="edit-stay">{T('Change my dates','Cambiar mis fechas')}</button></div></div></section><div class="section stay-help"><p>{T('Your villa. Your way to book.','Tu villa. Tu forma de reservar.')}</p><a class="text-link" href="{AIRBNB}" target="_blank" rel="noopener">{T('Prefer Airbnb? View our listing','¿Prefieres Airbnb? Ver el anuncio')} ↗</a></div></main>{footer(lang,'stay')}{components(lang)}<script src="/assets/booking.js" defer></script></body></html>'''
    return s
